CREATE OR REPLACE FUNCTION public.claim_research_execution(_run_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE affected integer; BEGIN UPDATE public.research_runs SET status='running',started_at=now(),execution_lease_until=NULL WHERE id=_run_id AND user_id=auth.uid() AND status='pending' AND NOT is_demo; GET DIAGNOSTICS affected=ROW_COUNT; RETURN affected=1; END; $$;
GRANT EXECUTE ON FUNCTION public.claim_research_execution(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.finalize_research_report(_run_id uuid,_report jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE r public.research_runs; report_id uuid; BEGIN SELECT * INTO r FROM public.research_runs WHERE id=_run_id AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND OR r.status<>'running' THEN RAISE EXCEPTION 'Run is not active'; END IF; INSERT INTO public.research_reports(run_id,ticker,recommendation,price_target,conviction_score,risk_level,executive_summary,sections,lovable_credits,credit_basis) VALUES(r.id,r.ticker,_report->>'recommendation',(_report->>'price_target')::numeric,(_report->>'conviction_score')::integer,_report->>'risk_level',_report->>'executive_summary',_report,r.lovable_credits,r.credit_basis) RETURNING id INTO report_id; UPDATE public.research_runs SET status='completed',completed_at=now(),execution_lease_until=NULL WHERE id=r.id; INSERT INTO public.research_events(run_id,event_type,message) VALUES(r.id,'completed','Research report ready.'); RETURN report_id; END; $$;
REVOKE ALL ON FUNCTION public.finalize_research_report(uuid,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.finalize_research_report(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.save_agent_result(_output_id uuid,_result jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE run_uuid uuid; BEGIN SELECT o.run_id INTO run_uuid FROM public.agent_outputs o JOIN public.research_runs r ON r.id=o.run_id WHERE o.id=_output_id AND r.user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Output unavailable'; END IF; PERFORM 1 FROM public.research_runs WHERE id=run_uuid FOR UPDATE; UPDATE public.agent_outputs SET content=_result->>'text',status='completed',input_tokens=(_result->>'input')::integer,output_tokens=(_result->>'output')::integer,cost_usd=(_result->>'cost')::numeric,lovable_credits=(_result->>'credit')::numeric,credit_basis='calculated',usage_details=_result->'details' WHERE id=_output_id; UPDATE public.research_runs SET total_input_tokens=(SELECT COALESCE(sum(input_tokens),0) FROM public.agent_outputs WHERE run_id=run_uuid AND status='completed'),total_output_tokens=(SELECT COALESCE(sum(output_tokens),0) FROM public.agent_outputs WHERE run_id=run_uuid AND status='completed'),total_cost_usd=(SELECT COALESCE(sum(cost_usd),0) FROM public.agent_outputs WHERE run_id=run_uuid AND status='completed'),lovable_credits=(SELECT CASE WHEN count(*) FILTER(WHERE lovable_credits IS NULL)>0 THEN NULL ELSE COALESCE(sum(lovable_credits),0) END FROM public.agent_outputs WHERE run_id=run_uuid AND status='completed'),credit_basis='calculated' WHERE id=run_uuid; END; $$;
REVOKE ALL ON FUNCTION public.save_agent_result(uuid,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_agent_result(uuid,jsonb) TO authenticated;